  // so both the nonce and the resulting session cookie belong to that same host.
  const signInOrigin = 'https://my-first-project-gamma-ashy.vercel.app';
  const nextQuery=new URLSearchParams();for(const key of ['view','cafe','plan'])if(typeof req.query?.[key]==='string'&&req.query[key].length<100)nextQuery.set(key,req.query[key]);
  const nextPath='/members'+(nextQuery.size?'?'+nextQuery.toString():'');
  if (origin !== signInOrigin) return redirect(res, signInOrigin + nextPath);
  setCookie(res,'__Host-coffee-return',nextPath,{maxAge:600});
  const rawNonce = randomBytes(32).toString('hex');
  setCookie(res, nonceName, rawNonce, { maxAge: 600, sameSite: 'none' });
  const hashedNonce = createHash('sha256').update(rawNonce).digest('hex');
