export function validateCoffeePreferences(body) {
 if(!body || typeof body!=='object') throw Error('Tell us what your coffee break looks like.');
 const areas=['Morningside Heights','Manhattanville / West Harlem','Upper West Side'];
 if(!areas.includes(body.area)) throw Error('Choose one of our three supported NYC neighborhoods.');
 if(!['Reset & unwind','Focus & study','Catch up with a friend','Explore new coffee'].includes(body.mood)) throw Error('Choose your mood.');
 const budget=Number(body.budget),duration=Number(body.duration);
 if(!Number.isInteger(budget)||budget<5||budget>50) throw Error('Choose a per-person budget from $5 to $50.');
 if(![30,60,90,120].includes(duration)) throw Error('Choose a visit of 30, 60, 90 or 120 minutes.');
 if(typeof body.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(body.date)||!Number.isFinite(Date.parse(body.date+'T12:00:00Z'))||new Date(body.date+'T12:00:00Z').toISOString().slice(0,10)!==body.date) throw Error('Choose a valid date.');
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 if(body.date<today || Date.parse(body.date)-Date.parse(today)>30*86400000) throw Error('Choose today or a date within the next 30 days.');
 if(typeof body.time!=='string'||!/^([01]\d|2[0-3]):[0-5]\d$/.test(body.time)) throw Error('Choose a valid arrival time.');
 const needs=typeof body.needs==='string'?body.needs.trim():'';
 if(needs.length>400) throw Error('Keep your preferences under 400 characters.');
 return {area:body.area,mood:body.mood,budget,duration,date:body.date,time:body.time,needs};
}
export function eligibleCoffeePlaces(p) {
 const day=new Date(p.date+'T12:00:00Z').getUTCDay(),minute=Number(p.time.slice(0,2))*60+Number(p.time.slice(3));
 return coffeePlaces.filter(c=>c.areas.includes(p.area)&&c.hours&&!c.restricted&&minute>=c.hours[day][0]&&minute+p.duration<=c.hours[day][1]);
}
