export function validateJournal(body) {
 if(!body || typeof body!=='object' || Array.isArray(body))throw Error('Please complete your visit details.');
 const result={};
 for(const [key,max] of Object.entries({cafe_name:160,cafe_address:300,drink:120,mood:80,notes:3000,caption:500})){
  const value=body[key]??''; if(typeof value!=='string'||value.length>max)throw Error('Please shorten your '+key.replaceAll('_',' ')+'.');result[key]=value.trim();
 }
 if(!result.cafe_name)throw Error('Add the café name.');
 const date=body.visit_date;if(typeof date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(date)||date<'2000-01-01'||date>'2100-12-31'||Number.isNaN(Date.parse(date))||new Date(date+'T12:00:00Z').toISOString().slice(0,10)!==date)throw Error('Choose a valid visit date.');
 result.visit_date=date;result.rating=body.rating===''||body.rating==null?null:Number(body.rating);
 if(result.rating!==null&&(!Number.isInteger(result.rating)||result.rating<1||result.rating>5))throw Error('Choose a rating from 1 to 5.');
 result.image_data=body.image_data||null;if(result.image_data)validateImage(result.image_data);
 return result;
}
